entries[46755] = { ["name"] = "Great Golden Kodo", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Thunder Bluff\n- Exalted\nSell Price:\n\"An alpha member of the herd, this kodo is a prime example of the mighty creatures which thunder through the Southern Barrens.\"\nVendor:\nDoru Thunderhorn\nZone:\nIcecrown\nCost:" }
entries[46756] = { ["name"] = "Great Red Elekk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exodar\n- Exalted\nSell Price:\n\"Never seen in Nagrand, the first red elekk calves were born in Azeroth after the Exodar's arrival. Some breeders theorize that the unique coloration is somehow caused by the same radiation which ravaged Bloodmyst Isle.\"\nVendor:\nIrisee\nZone:\nIcecrown\nCost:" }
entries[46757] = { ["name"] = "Swift Burgundy Wolf", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Orgrimmar\n- Exalted\nSell Price:\n\"The wolves of the Horde are befriended, not domesticated.\"\nVendor:\nFreka Bloodaxe\nZone:\nIcecrown\nCost:" }
entries[46758] = { ["name"] = "Swift Gray Steed", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Stormwind\n- Exalted\nSell Price:\n\"A veteran of some of the toughest battles fought by the Argent Crusade.\"\nVendor:\nCorporal Arthur Flew\nZone:\nIcecrown\nCost:" }
entries[46759] = { ["name"] = "Swift Moonsaber", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Darnassus\n- Exalted\nSell Price:\n\"Many night elves revere these proud mounts because their shimmering coats symbolize the goddess of the moon, Elune.\"\nVendor:\nRook Hawkfist\nZone:\nIcecrown\nCost:" }
entries[46760] = { ["name"] = "Swift Purple Raptor", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Darkspear Trolls\n- Exalted\nSell Price:\n\"Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become mount, guardian, and friend.\"\nVendor:\nSamamba\nZone:\nIcecrown\nCost:" }
entries[46761] = { ["name"] = "Swift Red Hawkstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Silvermoon City\n- Exalted\nSell Price:\n\"What do you mean is it dyed? Oh, the bird. We did touch up the red just a little. -Trellis Morningsun\"\nVendor:\nTrellis Morningsun\nZone:\nIcecrown\nCost:" }
entries[46762] = { ["name"] = "Swift Violet Ram", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Ironforge\n- Exalted\nSell Price:\n\"The Barak Tor'ol ram's thick bony skull and massive horns make it the ideal mount for charging through groups of armored enemies.\"\nVendor:\nDerrick Brindlebeard\nZone:\nIcecrown\nCost:" }
entries[46763] = { ["name"] = "Turbostrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Gnomeregan\n- Exalted\nSell Price:\n\"The mirror's not so you can look back, but so your foes can see something besides your tailpipes. -Rillie Spindlenut\"\nVendor:\nRillie Spindlenut\nZone:\nIcecrown\nCost:" }
